// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner = address(0x1234);

    function setUp() public {
        vm.prank(owner);
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 initialBalance, uint256 withdrawAmount) public {
        vm.assume(initialBalance >= 1 ether);
        vm.assume(initialBalance <= 1000 ether);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= initialBalance);

        vm.deal(address(c), initialBalance);

        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(owner);
        c.withdraw(withdrawAmount);

        uint256 ownerBalanceAfter = owner.balance;
        uint256 contractBalanceAfter = address(c).balance;

        assertEq(
            contractBalanceAfter + ownerBalanceAfter,
            contractBalanceBefore + ownerBalanceBefore
        );
    }
}
